from content_helpers import code, output, choice, lesson, section, program

def sections():
    return [section("ownership", "11. Владение и RAII", "Понимайте динамическую память, но предпочитайте автоматическое управление ресурсами.", [
        lesson("dynamic", "Динамическое время хранения", "Отделите жизнь объекта от локального имени указателя.",
            "new int(value) создаёт int в динамической памяти и возвращает указатель. delete p завершает жизнь этого объекта и освобождает выделенную память. После delete читать *p нельзя. Сам указатель не обнуляется автоматически; p=nullptr может сделать дальнейшее случайное использование заметнее, но не исправляет другие копии того же адреса.\n\nЕсли потерять единственный путь к выделенному объекту без освобождения, получится утечка. Повторный delete того же объекта недопустим. Для массивного new[] нужен delete[], не обычный delete. В этом уроке рассматриваем только одиночный int и одну пару new/delete. Это изучение механизма, а не рекомендация вручную управлять памятью в обычном приложении. Следующий урок заменит ручную пару владельцем RAII.",
            program('int* p = new int(7);\nstd::cout << *p;\ndelete p;\np = nullptr;'),
            "Указатель p как локальная переменная и созданный new объект — разные объекты с разным временем жизни. Завершение жизни p не вызывает delete автоматически. Не стоит называть любое размещение «кучей» обязательной физической структурой стандарта: это распространённая модель реализации динамического хранения.",
            "Для каждого ручного new нужен ровно соответствующий владелец и освобождение. После delete объект недоступен.", [
                code("single", "Один динамический объект", 'Ввод: n (−100…100). Создайте int через new int(n), увеличьте значение на 1, выведите его, затем освободите через delete. После освобождения не разыменовывайте.', 'int n = 0;\nstd::cin >> n;\nint* p = new int(n);\n++(*p);\nstd::cout << *p;\ndelete p;\np = nullptr;', [("7", "8"), ("-1", "0"), ("-100", "-99"), ("100", "101"), ("0", "1")], ["Освобождение должно идти после последнего использования.", "Меняйте *p, а не p; delete вызывайте один раз."], "Вывод до delete допустим, вывод через тот же указатель после delete — нет."),
                code("copyvalue", "Сохраните значение, не адрес", 'Ввод: n (−100…100). Создайте динамический int со значением 2*n, скопируйте *p в обычный int result, освободите объект и выведите result.', 'int n = 0;\nstd::cin >> n;\nint* p = new int(2 * n);\nint result = *p;\ndelete p;\np = nullptr;\nstd::cout << result;', [("4", "8"), ("0", "0"), ("-5", "-10"), ("100", "200"), ("-100", "-200")], ["Копия int самостоятельна.", "Сохраните result до освобождения объекта."], "Самостоятельное значение может безопасно пережить свой источник."),
                choice("delete", "После delete", 'Что верно после delete p для одиночного int, если p был единственным владельцем?', ["Чтение *p по-прежнему безопасно до следующего new", "Объект закончил жизнь; чтение через старый указатель недопустимо", "Сам p обязательно стал nullptr"], 1, ["Освобождение не зависит от того, успел ли кто-то перезаписать память.", "delete не присваивает новое значение переменной p."], "Наблюдаемое старое число в памяти не создаёт гарантии безопасности."),
                code("null", "Освободите и обнулите", 'Ввод: n (−100…100). Выделите int(n), выведите значение, затем delete, затем присвойте p=nullptr и выведите через пробел результат p==nullptr (1).', 'int n = 0;\nstd::cin >> n;\nint* p = new int(n);\nstd::cout << *p;\ndelete p;\np = nullptr;\nstd::cout << " " << (p == nullptr);', [("9", "9 1"), ("0", "0 1"), ("-100", "-100 1"), ("100", "100 1"), ("5", "5 1")], ["Проверка сравнивает указатель, не читает удалённый объект.", "Обнулите p явно после delete."], "Обнуление помогает этому имени, но не обнуляет возможные другие указатели на тот же объект.")
            ], ["new", "delete", "владение"]),
        lesson("raii", "unique_ptr и автоматическое освобождение", "Пусть объект-владелец управляет ресурсом.",
            "RAII связывает ресурс со временем жизни объекта-владельца. std::unique_ptr<int> из <memory> владеет одиночным int и освобождает его при разрушении владельца, включая обычный выход из блока и раскрутку стека при исключении. auto p=std::make_unique<int>(7); создаёт владельца без явного new. Доступ к значению — через *p. Ручной delete для объекта, которым владеет unique_ptr, не нужен и опасен.\n\nВладение unique_ptr нельзя копировать. auto q=std::move(p); передаёт его другому unique_ptr; подключите <utility>. В этом конкретном перемещении p становится пустым, q владеет прежним объектом. std::move сама по себе — преобразование, а фактический перенос выполняет операция перемещения типа. reset() освобождает управляемый объект и делает владельца пустым.",
            program('auto p = std::make_unique<int>(7);\nauto q = std::move(p);\nstd::cout << *q << " " << (p == nullptr);', "iostream memory utility"),
            "RAII не означает «программа не может завершиться аварийно и никогда ничего не потеряет». Например, немедленное завершение процесса или сбой системы могут обходить обычное разрушение объектов. В нормальном управлении потоком автоматический владелец существенно уменьшает число путей утечки.",
            "Предпочитайте make_unique и контейнеры. Владение передают явно, доступ через пустой unique_ptr запрещён.", [
                code("owned", "Автоматический владелец", 'Ввод: n (−100…100). Через make_unique создайте int(n), прибавьте 5 и выведите значение. Не используйте ручной delete.', 'int n = 0;\nstd::cin >> n;\nauto p = std::make_unique<int>(n);\n*p += 5;\nstd::cout << *p;', [("7", "12"), ("-5", "0"), ("-100", "-95"), ("100", "105"), ("0", "5")], ["Тип p можно вывести через auto.", "Освобождение выполнит unique_ptr при выходе из main."], "Ответственность за освобождение хранится в типе владельца.", headers="iostream memory"),
                code("transfer", "Передача владения", 'Ввод: n (−100…100). Создайте p=make_unique<int>(n), переместите в q, выведите (p==nullptr) и *q через пробел.', 'int n = 0;\nstd::cin >> n;\nauto p = std::make_unique<int>(n);\nauto q = std::move(p);\nstd::cout << (p == nullptr) << " " << *q;', [("8", "1 8"), ("-2", "1 -2"), ("-100", "1 -100"), ("0", "1 0"), ("100", "1 100")], ["unique_ptr не копируется обычным auto q=p.", "Используйте std::move(p), затем читайте только через q."], "Для unique_ptr после такой передачи источник пуст; не обобщайте это состояние на все типы после std::move.", headers="iostream memory utility"),
                choice("manual", "Два владельца освобождения", 'Нужно ли писать delete p.get() для int, которым продолжает владеть unique_ptr p?', ["Нет, это нарушает модель владения и может привести к повторному освобождению", "Да, иначе память всегда утечёт", "Да, но только для отрицательных чисел"], 0, ["get даёт адрес, не отменяя владения.", "unique_ptr позже тоже попытается освободить свой объект."], "Ручное освобождение управляемого ресурса не должно дублировать ответственность владельца."),
                code("reset", "Явное завершение ресурса", 'Ввод: n (−100…100). Создайте p как unique_ptr<int>, владеющий int со значением n. Скопируйте значение в saved, вызовите reset(), выведите saved и результат p==nullptr.', 'int n = 0;\nstd::cin >> n;\nauto p = std::make_unique<int>(n);\nint saved = *p;\np.reset();\nstd::cout << saved << " " << (p == nullptr);', [("4", "4 1"), ("0", "0 1"), ("-100", "-100 1"), ("0", "0 1"), ("100", "100 1")], ["Копируйте значение до reset.", "После reset допустимо сравнить p с nullptr, но не читать *p."], "Владелец может освободить ресурс раньше конца своего блока.", headers="iostream memory")
            ], ["RAII", "unique_ptr", "move"]),
        lesson("invalidation", "Когда адреса устаревают", "Не храните доступ к элементу через изменение структуры контейнера.",
            "vector может перераспределить память при росте. Если push_back вызвал перераспределение, прежние указатели, ссылки и итераторы на его элементы недействительны. Если перераспределения не было, для push_back ссылки на прежние элементы сохраняются, но прежний end меняется. Поэтому правило «всегда всё ломается» тоже неточно.\n\nБезопасная простая стратегия — сохранить индекс, выполнить добавление, заново получить элемент по этому индексу, если он всё ещё обозначает нужную запись. reserve задаёт ёмкость, но не создаёт элементы; resize изменяет size и создаёт/удаляет элементы. Удаление может сдвигать записи, поэтому индекс сам по себе не универсальный стабильный ID. В приложении учебный прогресс связан со стабильными ID, не с позициями массива.",
            program('std::vector<int> v = {4, 7};\nint index = 0;\nv.push_back(9);\nstd::cout << v[index];', "iostream vector"),
            "Нельзя написать переносимый тест, который всегда предсказывает факт перераспределения по одному push_back без знания ёмкости и операции. Правильный вопрос — что гарантирует контракт операции в каждом случае. Не обращайтесь к старому адресу «для проверки, сохранился ли он».",
            "Размер, ёмкость, позиция и стабильный идентификатор — разные вещи. После структурных изменений пересматривайте доступы.", [
                code("reacquire", "Получите доступ заново", 'Ввод: n (1…100), n чисел (−100…100), затем added. Запомните индекс первого элемента, добавьте added через push_back, выведите первый элемент через заново выполненную индексацию и новый размер.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v(n);\nfor (int i = 0; i < n; ++i) { std::cin >> v[i]; }\nint added = 0;\nstd::cin >> added;\nint index = 0;\nv.push_back(added);\nstd::cout << v[index] << " " << v.size();', [("2 4 7 9", "4 3"), ("1 -2 8", "-2 2"), ("1 5 0", "5 2"), ("3 -1 -2 -3 4", "-1 4"), ("2 100 -100 -50", "100 3")], ["Не сохраняйте int* на первый элемент до push_back.", "Сохраните 0 как индекс, затем обратитесь v[index] после роста."], "Добавление в конец не меняет логический номер старого первого элемента.", headers="iostream vector"),
                code("reserve", "Ёмкость — не элементы", 'Ввод: n (0…100). Создайте пустой vector<int>, вызовите reserve(n), выведите size, затем добавьте число 7 и снова выведите size через пробел. Не выводите capacity: её точное значение не требуется.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v;\nv.reserve(n);\nstd::cout << v.size();\nv.push_back(7);\nstd::cout << " " << v.size();', [("10", "0 1"), ("0", "0 1"), ("1", "0 1"), ("100", "0 1"), ("5", "0 1")], ["reserve выделяет возможность роста, не создавая элементы.", "Размер изменит только push_back в этой программе."], "Гарантируется достаточная ёмкость, но размер остаётся нулевым до добавления.", headers="iostream vector"),
                choice("push", "Точная гарантия", 'Когда push_back у vector делает прежние указатели на элементы недействительными?', ["Если операция вызвала перераспределение памяти", "Никогда", "Только если добавлено отрицательное число"], 0, ["Значение элемента не определяет адресную стабильность.", "Существенно, хватило ли прежней ёмкости."], "Условие перераспределения позволяет дать точное правило вместо неверного «всегда» или «никогда»."),
                code("resize", "Создание элементов", 'Ввод: n (0…100). Создайте пустой vector<int>, вызовите resize(n), выведите размер и сумму элементов через пробел. Новые int инициализируются нулями.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> v;\nv.resize(n);\nint sum = 0;\nfor (int x : v) { sum += x; }\nstd::cout << v.size() << " " << sum;', [("3", "3 0"), ("0", "0 0"), ("1", "1 0"), ("100", "100 0"), ("50", "50 0")], ["В отличие от reserve, resize меняет size.", "Сумма новых нулевых int равна нулю."], "Обращение к созданным элементам теперь допустимо в пределах нового размера.", headers="iostream vector")
            ], ["инвалидация", "reserve", "resize"])
    ])]
